section PCA
variable {P R : Type}
def canAccess (inScope : P → R → Prop) (isPriv : P → Prop) (isUnowned : R → Prop)
    (c : P) (r : R) : Prop := inScope c r ∨ isPriv c ∨ isUnowned r

Theorem: With empty scope and no escapes, nothing is accessible: (∀ c r, ¬inScope c r) → (∀ c, ¬isPriv c) → (∀ r, ¬isUnowned r) → ¬ canAccess inScope isPriv isUnowned c r.

